mapper.select:
SELECT id, name, code, description, status, level, landing_page, created_at, updated_at
FROM roles

ORDER BY

    ${sort}
    id DESC

LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE roles
name = #{name}, description = #{description}, status = #{status}, updated_at = datetime('now')
WHERE id = #{id}

UPDATE roles SET status = #{status}, updated_at = datetime('now')
WHERE id IN
#{id}

mapper.select:
SELECT p.id, p.name, p.code, p.resource, p.action, p.created_at, p.updated_at
FROM permissions p JOIN role_permissions rp ON rp.permission_id = p.id
WHERE rp.role_id = #{roleId}

SELECT DISTINCT p.code FROM permissions p
JOIN role_permissions rp ON p.id = rp.permission_id
JOIN (
    SELECT ur.role_id FROM user_roles ur WHERE ur.user_id = #{userId}
    UNION
    SELECT dr.role_id FROM department_roles dr JOIN user_departments ud ON ud.department_id = dr.department_id WHERE ud.user_id = #{userId}
) r ON r.role_id = rp.role_id

SELECT role_id, scope_type FROM role_data_scopes
WHERE role_id IN
#{id}
AND resource = #{resource}
